const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function connectPublicAI(client){const status=await client.status();if(!status.publicAccess)throw Error('当前地址未启用公开 AI 服务');if(!status.configured)throw Error('网站 AI 服务尚未完成模型配置');client.publicAccess=true;const session=await client.request('/api/public/session',{});client.token=session.token;return {status,session};}
export function openPublicAIInfo({modal,config,client,reconnect,mode,changeMode,onAnalyze}){const d=modal('<div id="public-info"><p>正在获取服务状态…</p></div>','网站 AI · 公开体验');const body=d.querySelector('#public-info');let closed=false;d.addEventListener('close',()=>closed=true,{once:true});
 async function show(){try{if(!config.active)throw Error(config.note||'公开 AI 尚未上线');let api=client();if(!api.publicAccess||!api.token){await reconnect();api=client();}const info=await api.request('/api/public/usage');if(closed)return;body.innerHTML=`<div class="setup-success"><b>网站 AI 已连接，无需密码或 API Key</b><p>使用 ${esc(config.model)}。模型密钥保存在网站后端，只有点击分析或生成方案才会调用模型。</p></div><div class="kpis">${[['本次已提交评论',info.used.comments,info.limits.comments],['本次已生成方案',info.used.plans,info.limits.plans],['本次已请求摘要',info.used.summaries,info.limits.summaries]].map(([l,n,m])=>`<div class="kpi"><span>${l}</span><strong>${n}<small>/ ${m}</small></strong></div>`).join('')}</div><div class="notice">同一网络：每分钟最多 ${info.limits.requestsPerMinute} 次操作，每天最多 ${info.limits.commentsPerNetworkDay} 条评论、${info.limits.plansPerNetworkDay} 份方案。全站同时最多 ${info.limits.concurrency} 个模型请求；另有全站每日共享上限。</div><p class="muted">同一 Wi-Fi 的访客可能共用网络限额。访客会话和网络双重限制，刷新不能重置全站额度；失败请求也可能计入体验限制。每日额度按北京时间重置，用量为保守记账，不等于供应商账单。登录或查看此面板不调用模型。</p><label>分析方式<select id="public-mode"><option value="ai" ${mode()==='ai'?'selected':''}>真实 AI（网站提供）</option><option value="rules" ${mode()==='rules'?'selected':''}>规则与模板演示（不调用模型）</option></select></label><div class="toolbar"><button id="public-start" class="primary">开始分析评论 →</button><button id="public-refresh">刷新用量</button></div><p class="muted">连接成功表示后端和访客会话可用，不表示模型的每次输出都准确；原文证据仍需人工复核。</p>`;body.querySelector('#public-mode').onchange=async e=>{await changeMode(e.target.value);};body.querySelector('#public-start').onclick=()=>{d.close();onAnalyze();};body.querySelector('#public-refresh').onclick=show;}catch(e){if(closed)return;body.innerHTML=`<div class="notice error"><b>AI 暂时没有连接成功</b><p>${esc(e.message)}</p></div><p>请稍后重试。原有数据和规则演示仍可使用，不会用模拟结果冒充 AI。</p><button id="public-retry" class="primary">重新连接</button>`;body.querySelector('#public-retry').onclick=async()=>{try{await reconnect();await show();}catch(e){body.querySelector('.notice p').textContent=e.message;}};}}
 show();return d;
}
